const CACHE='tournoi-eps-v23-20261011';
const ASSETS=['./','./index.html','./style.css','./app.js','./engine.js','./planning.js','./controls.js','./rackets.js','./fonts/outfit-variable.ttf','./fonts/barlow-condensed-bold.ttf','./exchange.js','./vendor/pako-inflate.min.js','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS))));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('tournoi-eps-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy))}return response}).catch(async()=>await caches.match(event.request)||((event.request.mode==='navigate')?await caches.match('./index.html'):Response.error())))});
